/*
 CAFETERIA - INSTALACION COMPLETA EN UNA SOLA EJECUCION
 Origen: 01_BD_CAFETERIA_TRANSACCIONAL(1).sql
 Crea la base si no existe y ejecuta el esquema + registros originales.
 IMPORTANTE: Si la base ya existe, se detiene para evitar duplicaciones.
 Requiere SQL Server 2022 / SSMS, permiso CREATE DATABASE.
*/
USE master;
GO
IF DB_ID(N'BD_Cafeteria') IS NOT NULL
BEGIN
    RAISERROR(N'Ya existe BD_Cafeteria. Para evitar sobrescribir datos, ejecute en una instancia sin esa base o cambie el nombre en este script.', 16, 1);
    SET NOEXEC ON;
END
GO
IF DB_ID(N'BD_Cafeteria') IS NULL EXEC(N'CREATE DATABASE [BD_Cafeteria]');
GO
USE [BD_Cafeteria];
GO
