GO
CREATE VIEW [dbo].[VW_INVENTARIO_PRODUCTOS] AS
SELECT
    i.id_inventario,
    p.id_producto,
    p.nombre_producto,
    i.cantidad_disponible,
    i.fecha_actualizacion
FROM INVENTARIO i
INNER JOIN PRODUCTO p ON i.id_producto = p.id_producto
GO
